insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 7, 'Vi servos a cavalo, e príncipes que andavam [a pé] como [se fossem] servos sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 8, 'Quem cavar uma cova, nela cairá; e quem romper um muro, uma cobra o morderá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 9, 'Quem extrai pedras, por elas será ferido; e quem parte lenha, correrá perigo por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 10, 'Se o ferro está embotado, e não afiar o corte, então deve se pôr mais forças; mas a sabedoria é proveitosa para se ter sucesso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 11, 'Se a cobra morder sem estar encantada, então proveito nenhum tem a fala do encantador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 12, 'As palavras da boca do sábio são agradáveis; porém os lábios do tolo o devoram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 13, 'O princípio das palavras de sua boca é tolice; e o fim de sua boca [é] uma loucura ruim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 14, 'O tolo multiplica as palavras, [porém] ninguém sabe o que virá no futuro; e quem lhe fará saber o que será depois dele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 15, 'O trabalho dos tolos lhes traz cansaço, porque não sabem ir à cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 16, 'Ai de ti, ó terra cujo rei é um menino, e cujos príncipes comem pela madrugada!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 17, 'Bem-aventurada é tu, ó terra, cujo rei é filho de nobres, e cujos príncipes comem no tempo [devido] , para se fortalecerem, e não para se embebedarem!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 18, 'Pela muita preguiça o teto se deteriora; e pala frouxidão das mãos a casa tem goteiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 19, 'Para rir se fazem banquetes, e o vinho alegra aos vivos; mas o dinheiro responde por tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 10, 20, 'Nem mesmo em pensamento amaldiçoes ao rei, nem também no interior de teu quarto amaldiçoes ao rico, porque as aves dos céus levam o que foi falado, e os que tem asas contam o que foi dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 11, 1, 'Lança teu pão sobre as águas, porque depois de muitos dias tu o encontrarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 11, 2, 'Dá uma parte a sete, e até a oito; porque não sabes que mal haverá sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 11, 3, 'Se as nuvens estiverem cheias, há chuva sobre a terra; e se a árvore cair, seja para ou sul ou seja para o norte, no lugar em que a árvore cair, ali ela ficará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 11, 4, 'Quem ficar dando atenção ao vento, nunca semeará; e o que olhar para as nuvens nunca ceifará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 11, 5, 'Assim como tu não sabes qual é o caminho do vento, [nem] como se formam os ossos [do feto] no ventre da grávida, assim também tu não sabes a obra de Deus, que faz todas as coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 11, 6, 'Pela manhã semeia tua semente, e à tarde não retires tua mão; pois tu não sabes qual [tentativa] dará certo, se uma, se outra, ou se ambas [as tentativas] serão boas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 11, 7, 'Certamente a luz é agradável, e ver o sol é bom para os olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 11, 8, 'Mesmo se o homem viver muitos anos, [e] em todos eles se alegrar, ele também deve se lembrar dos dias de trevas, porque serão muitos. Tudo o que acontece é futilidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 11, 9, 'Alegra-te, rapaz, em tua juventude; e agrada o teu coração nos dias de tua juventude; e anda pelos caminhos do teu coração, e na vista de teus olhos; sabe, porém, que por todas estas coisas, Deus te trará a julgamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 11, 10, '[Portanto] afasta o desagrado de teu coração, e tira de tua carne o mal; pois a adolescência e a juventude são futilidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 1, 'Portanto lembra-te de teu Criador nos dias de tua juventude, antes que venham os dias ruins, e cheguem os anos, dos quais venhas a dizer: Não tenho neles contentamento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 2, 'Antes que se escureçam o sol, a luz, a lua e as estrelas; e voltem as nuvens após a chuva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 3, 'No dia em que os guardas da casa tremerem, e os homens fortes se encurvarem; e cessarem os moedores, por terem diminuído, e se escurecerem os que olham pelas janelas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 4, 'E as portas da rua se fecharem, enquanto se abaixa o ruído da moedura; e se levantar a voz das aves, e todas as vozes do canto se encurvarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 5, 'Como também [quando] temerem as coisas altas, e houver espantos no caminho; e florescer a amendoeira, e o gafanhoto se tornar pesado, e acabar o apetite; porque o homem vai para sua casa eterna, e os que choram andarão ao redor da praça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 6, 'Antes que se afrouxe a correia de prata, e de despedace a vasilha de ouro; e se quebre o vaso junto à fonte, e se despedace a roda junto ao poço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 7, 'E o pó volte à terra, assim como era; e o espírito volte a Deus, que o deu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 8, 'Futilidade das futilidades! - diz o pregador - Tudo é futilidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 9, 'Além do Pregador ter sido sábio, ele também ensinou conhecimento ao povo. Ele ouviu, investigou e pôs em ordem muitos provérbios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 10, 'O Pregador procurou achar palavras agradáveis, e escreveu coisas corretas, palavras de verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 11, 'As palavras dos sábios são como aguilhões, e como pregos bem fixados [pelos] mestres das congregações, [que] foram dadas pelo único Pastor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 12, 'Além destas coisas, filho meu, tem cuidado; fazer muitos livros é [algo que] não tem fim; e estudar muito cansa a carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 13, 'De tudo o que foi ouvido, a conclusão é: teme a Deus, e guarda os mandamentos dele; porque isto é [o dever de] todo homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 21, 'Eclesiastes', 'Ec', 12, 14, 'Porque Deus trará a julgamento toda obra, até mesmo tudo o que está encoberto, seja bom ou mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 1, 'Cântico dos cânticos, que é de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 2, '[Ela] : Beije-me ele com os beijos de sua boca, porque teu amor é melhor do que o vinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 3, 'O cheiro dos teus perfumes é agradável; teu nome é [como] perfume sendo derramado, por isso as virgens te amam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 4, 'Toma-me contigo, e corramos; traga-me o rei aos seus quartos.[Moças] : Em ti nos alegraremos e nos encheremos de alegria; nos agradaremos mais de teu amor do que do vinho;[Ela] : Elas estão certas em te amar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 5, 'Eu sou morena, porém bela, ó filhas de Jerusalém: [morena] como as tendas de Quedar, [bela] como as cortinas de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 6, 'Não fiquem me olhando por eu ser morena, pois o sol brilhou sobre mim; os filhos de minha mãe se irritaram contra mim, [e] me puseram para cuidar de vinhas; [porém] minha própria vinha, que me pertence, não cuidei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 7, 'Dize-me, amado de minha alma: onde apascentas [o teu gado] ? Onde [o] recolhes ao meio- dia? Para que ficaria eu como que coberta com um véu por entre os gados de teus colegas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 8, '[Ele] : Se tu, a mais bela entre as mulheres, não sabes, sai pelos rastros das ovelhas, e apascenta tuas cabras junto às tendas dos pastores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 9, 'Eu te comparo, querida, às éguas das carruagens de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 10, 'Agradáveis são tuas laterais da face entre os enfeites, teu pescoço entre os colares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 11, 'Enfeites de ouro faremos para ti, com detalhes de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 12, '[Ela] : Enquanto o rei está sentado à sua mesa, meu nardo dá a sua fragrância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 13, 'Meu amado é para mim [como] um saquinho de mirra que passa a noite entre meus seios;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 14, 'Meu amado é para mim [como] um ramalhete de hena nas vinhas de Engedi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 15, '[Ele] : Como tu és bela, minha querida! Como tu és bela! Teus olhos são [como] pombas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 16, '[Ela] : Como tu és belo, meu amado! Como [tu és] agradável! E o nosso leito se enche de folhagens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 1, 17, 'As vigas de nossa casa são os cedros, e nossos caibros os ciprestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 1, 'Eu sou a rosa de Sarom, o lírio dos vales.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 2, '[Ele] : Como um lírio entre os espinhos, assim é minha querida entre as moças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 3, '[Ela] : Como a macieira entre as árvores do bosque, assim é o meu amado entre os rapazes; debaixo de sua sombra desejo muito sentar, e doce é o seu fruto ao meu paladar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 4, 'Ele me leva à casa do banquete, e sua bandeira sobre mim é o amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 5, 'Sustentai-me com passas, fortalecei-me com maçãs; porque estou fraca de amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 6, '[Esteja] sua mão esquerda abaixo de minha cabeça, e sua direita me abraça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 7, 'Eu vos ordeno, filhas de Jerusalém: jurai pelas corças e pelas cervas do campo, que não acordeis, nem desperteis ao amor, até que ele queira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 8, '[Esta é] a voz do meu amado: vede-o vindo, saltando sobre os montes, pulando sobre os morros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 9, 'Meu amado é semelhante ao corço, ou ao filhote de cervos; eis que está atrás de nossa parede, olhando pelas janelas, observando pelas grades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 10, 'Meu amado me responde, e me diz:[Ele] : Levanta-te, querida minha, minha bela, e vem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 11, 'Porque eis que o inverno já passou; a chuva se acabou, e foi embora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 12, 'As flores aparecem na terra, o tempo da cantoria chegou; e ouve-se a voz da rolinha em nossa terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 13, 'A figueira está produzindo seus figos verdes, e as vides florescentes dão cheiro; levanta-te, querida minha, minha bela, e vem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 14, 'Pomba minha, que andas pelas fendas das rochas no oculto das ladeiras, mostra-me tua face, faze-me ouvir tua voz; porque tua voz é doce, e tua face agradável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 15, 'Tomai-nos as raposas, as raposinhas, que danificam as vinhas, porque nossas vinhas estão florescendo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 16, 'Meu amado é meu, e eu sou sua; ele apascenta entre os lírios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 2, 17, 'Antes do dia se romper, e das sombras fugirem, volta, amado meu, faze-te semelhante ao corço, ao filhote de cervos, sobre os montes de Beter.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 3, 1, '[Ela] :Durante as noites busquei em minha cama a quem minha alma ama; busquei-o, mas não o achei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 3, 2, 'Por isso me levantarei, e percorrerei a cidade, pelas ruas e pelas praças; buscarei a quem minha alma ama; busquei-o, mas não o achei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 3, 3, 'Os guardas que rondavam pela cidade me encontraram. [Eu lhes perguntei] : Vistes a quem minha alma ama?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 3, 4, 'Pouco [depois] de me afastar deles, logo achei a quem minha alma ama. Eu o segurei, e não o deixei ir embora, até eu ter lhe trazido à casa de minha mãe, ao cômodo daquela que me gerou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 3, 5, 'Eu vos ordeno, filhas de Jerusalém: jurai pelas corças e pelas cervas do campo que não acordeis nem desperteis ao amor, até que ele queira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 3, 6, 'Quem é esta, que sobe do deserto como colunas de fumaça, perfumada com mirra, incenso, e com todo tipo de pó aromático de mercador?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 3, 7, 'Eis a cama móvel de Salomão! Sessenta guerreiros estão ao redor dela, dentre os guerreiros de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 3, 8, 'Todos eles portando espadas, habilidosos na guerra; cada um com sua espada à cintura, para [o caso de haver] um ataque repentino de noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 3, 9, 'O rei Salomão fez para si uma liteira de madeira do Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 3, 10, 'Suas colunas ele fez de prata, seu assoalho de ouro, seu assento de púrpura; por dentro coberta com [a obra do] amor das filhas de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 3, 11, 'Saí, ó filhas de Sião, e contemplai ao rei Salomão, com a coroa a qual sua mãe o coroou, no dia de seu casamento, no dia da alegria do seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 1, '[Ele] : Como tu és bela, minha querida! Como tu és bela! Teus olhos por trás do véu são [como] pombas; teu cabelo é como um rebanho de cabras, que descem do monte Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 2, 'Teus dentes são como [ovelhas] tosquiadas, que sobem do lavatório; todas elas têm gêmeos, e nenhuma delas é estéril.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 3, 'Teus lábios são como uma fita de escarlate, e tua boca é bonita; tuas têmporas são como pedaços de romã por detrás do véu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 4, 'Teu pescoço é como a torre de Davi, construída como fortaleza; mil escudos estão nela pendurados, todos escudos de guerreiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 5, 'Teus dois seios são como dois filhos gêmeos da corça, que pastam entre os lírios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 6, 'Antes do dia nascer, e das sombras fugirem, irei ao monte de mirra, e ao morro do incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 7, 'Tu és bela, minha querida! Não há defeito algum em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 8, '[Vem] comigo do Líbano, ó esposa minha, vem comigo do Líbano; desce do cume de Amaná, do cume de Senir e de Hermom, das montanhas das leoas, dos montes dos leopardos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 9, 'Tomaste meu coração, minha irmã, minha esposa; tomaste o meu coração com um de teus olhos, com um colar de teu pescoço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 10, 'Como são agradáveis os teus amores, minha irmã, minha esposa! São bem melhores do que o vinho; e o cheiro de teus unguentos [é melhor] que todas as especiarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 11, 'Favos de mel descem de teus lábios, ó esposa; mel e leite estão debaixo de tua língua; e o cheiro de teus vestidos é como o cheiro do Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 12, 'Jardim fechado és tu, minha irmã, minha esposa; manancial fechado, uma fonte selada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 13, 'Tuas plantas são uma horta de romãs, com frutos excelentes: hena e nardo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 14, 'Nardo, açafrão, cálamo e canela; com todo tipo de árvores de incenso: mirra, aloés, com todas as melhores especiarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 15, '[Tu és] uma fonte de jardins, um poço de águas vivas que corre do Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 4, 16, '[Ela] : Levanta-te, vento norte! E vem, ó vento sul! Assopra em meu jardim, para que espalhem os seus aromas! Que meu amado venha a seu jardim, e coma de seus excelentes frutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 1, '[Ele] : Já cheguei ao meu jardim, minha irmã, [minha] esposa; colhi minha mirra com minha especiaria; comi meu mel, bebi meu vinho com meu leite. [Autor do poema (ou os amigos dos noivos)] : Comei, amigos; bebei, ó amados, e embebedai-vos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 2, '[Ela] : Eu estava dormindo, mas meu coração vigiava; era a voz de meu amado, batendo: Abre-me, minha irmã, minha querida, minha pomba, minha perfeita! Porque minha cabeça está cheia de orvalho, meus cabelos das gotas da noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 3, 'Já tirei minha roupa; como [voltarei] a vesti-la? Já lavei meus pés; como vou sujá-los [de novo] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 4, 'Meu amado meteu sua mão pelo buraco [da porta] ,e meu interior se estremeceu por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 5, 'Eu me levantei para abrir a meu amado; minhas mãos gotejavam mirra, e meus dedos [derramaram] mirra sobre os puxadores da fechadura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 6, 'Eu abri a porta ao meu amado, porém meu amado já tinha saído e ido embora; minha alma como que saía [de si] por causa de seu falar. Eu o busquei, mas não o achei; eu o chamei, mas ele não me respondeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 7, 'Os guardas que rondavam pela cidade me encontraram; eles me bateram [e] me feriram; os guardas dos muros tiraram de mim o meu véu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 8, 'Eu vos ordeno, filhas de Jerusalém: jurai que, se achardes o meu amado, dizei a ele que estou doente de amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 9, '[Moças] : Ó, tu, mais bela entre as mulheres, como é o teu amado, a quem tu amas mais do que qualquer outro? Como é este teu amado, mais amado que qualquer outro, por quem assim nos mandas jurar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 10, '[Ela] : Meu amado é radiante e rosado; ele se destaca entre dez mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 11, 'Sua cabeça é [como] o mais fino ouro; seus cabelos são crespos, pretos como o corvo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 12, 'Seus olhos são como pombas junto às correntes de águas, lavados em leite, colocados como [joias] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 13, 'As laterais de seu rosto como um canteiro de especiarias, [como] caixas aromáticas; seus lábios são [como] lírios, que gotejam fragrante mirra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 14, 'Suas mãos são [como] anéis de ouro com pedras de crisólitos; seu abdome [como] o brilhante marfim, coberto de safiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 15, 'Suas pernas são [como] colunas de mármore, fundadas sobre bases de ouro puro; seu aspecto é como o Líbano, precioso como os cedros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 5, 16, 'Sua boca é [cheia] de doçura, e ele é desejável em todos os sentidos; assim é o meu amado; assim é o meu querido, ó filhas de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 1, '[Moças] : Para onde foi o teu amado, ó tu mais bela entre as mulheres? Para que direção se virou o teu amado, para o procurarmos contigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 2, '[Ela] : Meu amado desceu ao seu jardim, aos canteiros de especiarias, para apascentar [seu rebanho] nos jardins, e para colher lírios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 3, 'Eu sou do meu amado, e meu amado é meu; ele apascenta entre os lírios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 4, '[Ele] : Tu és bela, minha querida, como Tirza, agradável como Jerusalém; és formidável como bandeiras [de exércitos] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 5, 'Afasta teus olhos de mim, pois eles me deixam desconcertado. Teu cabelo é como um rebanho de cabras, que descem de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 6, 'Teus dentes são como um rebanho de ovelhas, que sobem do lavatório; todas produzem gêmeos, e não há estéril entre elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 7, 'Como um pedaço de romã, assim são as laterais de teu rosto abaixo de teu véu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 8, 'Sessenta são as rainhas, e oitenta as concubinas; e as donzelas são inúmeras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 9, '[Porém] uma é a minha pomba, minha perfeita, a única de sua mãe, a mais querida daquela que a gerou. As moças a viram, e a chamaram de bem-aventurada; as rainhas e as concubinas a elogiaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 10, 'Quem é esta, que aparece como o nascer do dia, bela como a lua, brilhante como o sol, formidável como bandeiras [de exércitos] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 11, 'Desci ao jardim das nogueiras, para ver os frutos do vale; para ver se as videiras estavam floridas, [e se] as romãzeiras brotavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 12, 'Sem eu perceber, minha alma me pôs nas carruagens de meu nobre povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 6, 13, '[Moças] : Volta! Volta, Sulamita! Volta! Volta, e nós te veremos! [Ele] : Por que [quereis] ver a Sulamita, como a dança de duas companhias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 1, '[Ele] : Como são belos os teus pés nas sandálias, ó filha de príncipe! Os contornos de tuas coxas são como joias, [como] obra das mãos de um artesão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 2, 'Teu umbigo é [como] uma taça redonda, que não falta bebida; teu abdome é [como] um amontoado de trigo, rodeado de lírios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 3, 'Teus dois seios são como dois filhos gêmeos da corça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 4, 'Teu pescoço é como uma torre de marfim; teus olhos são [como] os tanques de peixes de Hesbom, junto à porta de Bate-Rabim. Teu nariz é como a torre do Líbano, que está de frente a Damasco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 5, 'Tua cabeça sobre ti, como o [monte] Carmelo, e o trançado dos cabelos cabeça como púrpura; o rei está [como que] atado em [tuas] tranças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 6, 'Como tu és bela! Como tu és agradável, ó amor em delícias!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 7, 'Esta tua estatura é semelhante à palmeira, e teus seios são [como] cachos [de uvas] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 8, 'Eu disse: Subirei à palmeira, pegarei dos seus ramos; e então teus seios serão como os cachos da videira, e a fragrância de teu nariz como o das maçãs.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 9, 'E tua boca [seja] como o bom vinho; [Ela] : [Vinho] que se entra a meu amado suavemente, e faz falarem os lábios dos que dormem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 10, 'Eu sou do meu amado, e ele me deseja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 11, 'Vem, amado meu! Saiamos ao campo, passemos as noites nas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 12, 'Saiamos de madrugada até às vinhas, vejamos se as videiras florescem, se suas flores estão se abrindo, se as romãzeiras já estão brotando; ali te darei os meus amores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 7, 13, 'As mandrágoras espalham seu perfume, e junto a nossas portas há todo tipo de excelentes frutos, novos e velhos; eu os guardei para ti, meu amado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 1, 'Como gostaria que tu fosses como meu irmão, que mamava os seios de minha mãe. Quando eu te achasse na rua, eu te beijaria, e não me desprezariam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 2, 'Eu te levaria e te traria à casa de minha mãe, aquela que me ensinou, e te daria a beber do vinho aromático, do suco de minhas romãs.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 3, 'Esteja sua mão esquerda debaixo de minha cabeça, e sua direita me abrace.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 4, 'Eu vos ordeno, filhas de Jerusalém: jurai que não acordeis, nem desperteis ao amor, até que ele queira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 5, '[Outros] : Quem é esta, que sobe da terra desabitada, reclinada sobre seu amado? [Ela] : Debaixo de uma macieira te despertei; ali tua mãe te teve com dores; ali te deu à luz aquela que te gerou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 6, 'Põe-me como selo sobre o teu coração, como selo sobre o teu braço; porque o amor é forte como a morte, e o ciúme é severo como o Xeol; suas brasas são brasas de fogo, labaredas intensas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 7, 'Muitas águas não poderiam apagar este amor, nem os rios afogá-lo; ainda que alguém desse todos os bens de sua casa por este amor, certamente o desprezariam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 8, '[Irmãos dela] : Temos uma irmã pequena, que ainda não têm seios; que faremos a esta nossa irmã, no dia que dela falarem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 9, 'Se ela for um muro, edificaremos sobre ela um palácio de prata; e se ela for uma porta, então a cercaremos com tábuas de cedro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 10, '[Ela] : Eu sou um muro, e meus seios como torres; então eu era aos olhos dele, como aquela que encontra a paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 11, 'Salomão teve uma vinha em Baal-Hamom; ele entregou esta vinha a uns guardas, e cada um [lhe] trazia como [faturamento] de seus frutos mil [moedas] de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 12, 'Minha vinha, que me pertence, está à minha disposição; as mil [moedas] de prata são para ti, Salomão, e duzentas para os guardas de teu fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 13, '[Ele] : Ó tu que habitas nos jardins, teus colegas prestam atenção à tua voz: faze com que eu [também possa] ouvi-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 22, 'Cânticos', 'Ct', 8, 14, '[Ela] : Vem depressa, meu amado! E faze-te semelhante ao corço, ao filhote de cervos, nas montanhas de ervas aromáticas!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 1, 'Visão de Isaías, filho de Amoz, a qual ele viu sobre Judá e Jerusalém, nos dias de Uzias, Jotão, Acaz [e] Ezequias, reis de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 2, 'Ouvi, ó céus; e escutai tu, terra, porque o SENHOR está falando: Eu criei filhos, e os fiz crescerem; porém eles se rebelaram contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 3, 'O boi conhece a seu dono, e o jumento [sabe] a manjedoura de seu possuidor; [mas] Israel não conhece, meu povo não entende.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 4, 'Ai da nação pecadora, do povo cheio de perversidade, semente de malfeitores, de filhos corruptos! Abandonaram ao SENHOR, provocaram a ira ao Santo de Israel, [dele] se afastaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 5, 'Para que seríeis espancados ainda mais? Vós vos rebelaríeis mais ainda. Toda a cabeça está enferma, e todo o coração fraco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 6, 'Desde a planta do pé até a cabeça, não há nele coisa sã. [Só há] feridas, inchaços e chagas podres, sem terem sido espremidas, feito curativos ou aliviadas com azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 7, 'Vossa terra é uma ruína; vossas cidades foram queimadas; vossa terra os estranhos devastaram diante de vossa presença, e está arruinada como que destruída por estranhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 8, 'E a filha de Sião ficou como uma cabana na vinha, como um barraco no pepinal, como uma cidade cercada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 9, 'Se o SENHOR dos exércitos não tivesse nos deixado alguns sobreviventes, teríamos sido como Sodoma, seríamos semelhantes aos de Gomorra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 10, 'Ouvi a palavra do SENHOR, vós líderes de Sodoma! Ouvi a Lei do nosso Deus, vós povo de Gomorra!:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 11, 'Para que me [serve] tantos sacrifícios vossos?,diz o SENHOR; Já estou farto de sacrifícios de queima de carneiros, e da gordura de animais cevados. Não me alegro com o sangue de bezerros, nem com o de cordeiros ou bodes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 12, 'Quando vindes a aparecer perante minha face, quem vos pediu isso de vossas mãos, de pisardes em meus pátios?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 13, 'Não tragais mais ofertas inúteis; [vosso] incenso para mim é abominação; não aguento [mais] as luas novas, os sábados, e as chamadas para o povo se reunir; [todas estas] se tornaram reuniões malignas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 14, 'Vossas luas novas e vossas solenidades, minha alma as odeia e elas me perturbam; estou cansado de [as] suportar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 15, 'Por isso quando estendeis vossas mãos, escondo meus olhos de vós; até quando fazeis muitas orações, eu não [vos] ouço; [porque] vossas mãos estão cheias de sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 16, 'Lavai-vos! Purificai-vos! Tirai a maldade de vossas atitudes perante meus olhos; parai de fazer maldades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 17, 'Aprendei a fazer o bem; procurai o que é justo; ajudai ao oprimido; fazei justiça ao órfão; defendei a causa da viúva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 18, 'Vinde, então, e façamos as contas,diz o SENHOR: ainda que vossos pecados sejam como a escarlate, eles ficarão brancos como a neve; ainda que sejam vermelhos como o carmesim, eles se tornarão como a lã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 19, 'Se quiserdes e ouvirdes, comereis o que é bom da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 20, 'Porém se recusardes e fordes rebeldes, sereis devorados pela espada;pois [foi assim que] a boca do SENHOR falou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 21, 'Como a cidade fiel se tornou uma prostituta! Ela estava cheia de juízo, justiça habitava nela; porém agora homicidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 22, 'Tua prata se tornou em escórias; teu vinho se misturou com água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 23, 'Teus príncipes são rebeldes, e companheiros de ladrões; cada um deles ama os subornos, e perseguem recompensas; não fazem justiça ao órfão, e não chega perante eles a causa das viúvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 24, 'Por isso diz o Senhor DEUS dos exércitos, o Poderoso de Israel: Ah, tomarei satisfações quanto aos meus adversários, e me vingarei de meus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 25, 'E tornarei minha minha mão contra ti, e purificarei por completo tuas escórias; e tirarei toda a tua impureza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 26, 'E restituirei a teus juízes, como da primeira vez, e a teus conselheiros, como no princípio; e depois disso te chamarão cidade da justiça, cidade fiel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 27, 'Sião será resgatada por meio do juízo; e os que retornarem a ela, por meio da justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 28, 'Mas para os transgressores e pecadores, serão juntamente quebrados; e os que deixarem ao SENHOR serão consumidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 29, 'Porque pelos carvalhos que cobiçastes serão confundidos; e pelos bosques que escolhestes sereis envergonhados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 30, 'Porque sereis como o carvalho ao qual suas folhas caem, e como o bosque que não tem água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 1, 31, 'E o forte se tornará em estopa, e sua obra, em faísca; e ambos serão juntamente queimados, e não haverá quem [os] apague.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 1, 'Palavra vista por Isaías, filho de Amoz, quanto a Judá e a Jerusalém:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 2, 'E acontecerá no últimos dias, que o monte da cada do SENHOR se firmará no cume dos montes, e se levantará por cima dos morros; e correrão em direção a ele todas as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 3, 'E muitos povos irão, e dirão: Vinde, subamos ao monte do SENHOR, à casa do Deus de Jacó, para que ele nos ensine sobre seus caminhos, e andemos em suas veredas; Porque de Sião virá a Lei, e de Jerusalém a palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 4, 'E ele julgará entre as nações, e repreenderá a muitos povos; e trocarão suas espadas em enxadas, e suas lanças em foices; não se levantará mais espada nação contra nação, nem aprenderão mais a fazer guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 5, 'Casa de Jacó, vinde, e andemos à luz do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 6, 'Mas tu, [SENHOR] , desamparaste a teu povo, à casa de Jacó; porque se encheram [dos costumes] do oriente, e são místicos como os filisteus; e se associam a filhos de estrangeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 7, 'A terra deles está cheia de prata e de ouro, e os tesouros deles não têm fim; a terra deles está cheia de cavalos, e as carruagens deles não têm fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 8, 'A terra deles também está cheia de ídolos; eles se inclinam perante as obras de suas próprias mãos, perante o que seus próprios dedos fizeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 9, 'Ali as pessoas se abatem, e os homens se humilham; por isso tu não os perdoarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 10, 'Entra nas rochas, e esconde-te no pó, por causa da temível presença do SENHOR, e da glória de sua majestade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 11, 'Os olhos arrogantes dos homens serão abatidos, e o orgulho dos homens será humilhado; e só o SENHOR será exaltado naquele dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 12, 'Porque o dia do SENHOR dos exércitos será contra o soberbo e o arrogante; e contra todo de que [se acha] exaltado, para que seja abatido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 13, 'E contra todos os cedros do Líbano, altos e elevados; e contra todos os carvalhos de Basã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 14, 'E contra todos os altos montes, e contra todos os morros elevados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 15, 'E contra toda torre alta, e contra todo muro fortificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 16, 'E contra todos os navios de Társis, e contra todas as pinturas desejadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 17, 'E a soberba do homem será humilhada, e o orgulho dos homens será abatido; e só o SENHOR será exaltado naquele dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 18, 'E todos os ídolos serão eliminados por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 19, 'Então entrarão nas cavernas das rochas, e nos buracos da terra, por causa da temível presença do SENHOR, e por causa de sua majestade, quando ele se levantar, para espantar a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 20, 'Naquele dia, o homem lançará seus ídolos de prata, e seus ídolos de ouro, que fizeram para se prostrarem diante deles, às toupeiras e aos morcegos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 21, 'E se porão nas fendas das rochas, e nas cavernas das penhas, por causa da temível presença do SENHOR, e por causa da glória de sua majestade, quando ele se levantar para espantar a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 2, 22, '[Portanto,] cessai de [confiar no] homem, cujo fôlego está em suas narinas; pois o que há nele que mereça se dar algum valor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 1, 'Porque eis que o Senhor DEUS dos exércitos tirará de Jerusalém e de Judá o apoio e o sustento: todas as fontes de comida e de água,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 2, 'O guerreiro, o soldado, o juiz, o profeta, o adivinho, e o ancião;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 3, 'O chefe de cinquenta, o nobre, o conselheiro, o sábio entre os artífices, e o que tem habilidade de falar palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 4, 'E [lhes] darei garotos como seus príncipes, e rapazes dominarão sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 5, 'E o povo será oprimido; um será contra o outro, e cada um contra seu próximo; o jovem se atreverá contra o ancião, e o reles contra o nobre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 6, 'Porque um homem tomará seu irmão da casa de seu pai, [e dirá] : Tu tens capa; sê nosso governante, e estejam estas ruínas debaixo de tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 7, '[Então] em tal dia ele levantará sua mão, dizendo: Não posso solucionar este problema; também em minha casa não há pão nem vestido algum; não me ponhais como governante do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 8, 'Porque Jerusalém tropeçou, e Judá está caído; pois sua língua e suas obras são contra o SENHOR, para irritar os seus gloriosos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 9, 'A aparência de seus rostos dão testemunho contra eles, e mostram abertamente seus pecados; assim como Sodoma, não os disfarçam. Ai da alma deles, porque estão fazendo mal a si mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 10, 'Dizei a justo, que o bem [lhe sucederá] ,que comerão do fruto de suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 11, 'Ai do perverso! O mal [lhe sucederá] ,porque lhe será feito conforme o trabalho de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 12, 'Os dominadores de meu povo são garotos, e mulheres dominam sobre ele; ah, meu povo, os que te guiam te enganam e confundem o caminho de tuas veredas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 13, 'O SENHOR se apresenta para brigar a causa judicial, e se põe para julgar aos povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 14, 'O SENHOR vem a juízo contra os anciãos de seu povo, e [contra] seus líderes: Pois vós consumistes a vinha, o despojo do pobre está em vossas casas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 15, 'Por que vós esmagastes ao meu povo, e moestes o rosto dos pobres?,diz o Senhor DEUS dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 16, 'Além disso o SENHOR diz: Dado que as filhas de Sião se exaltam, e andam com o pescoço levantado, e [procuram] seduzir com os olhos, e vão andando a passos curtos, fazendo ruídos com os ornamentos dos pés,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 17, 'Por isso o Senhor fará chagas no topo das cabeças das filhas de Sião, e descobrirá suas partes íntimas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 18, 'Naquele dia o Senhor tirará [delas] os enfeites: tornozeleiras, testeiras, gargantilhas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 19, 'Brincos, pulseiras, véus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 20, 'Chapéus, braceletes, cintos, bolsinhas de perfume, amuletos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 21, 'Anéis, pingentes de nariz,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 22, 'Vestidos de festa, mantas, capas, bolsas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 23, 'Transparências, saias de linho, toucas e túnicas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 24, 'E será que, no lugar de aromas haverá fedor; e no lugar de cinto [haverá] corda; e no lugar de cabelos cacheados [haverá] calvície, e no lugar de roupa luxuosa [haverá] roupa de saco; e queimadura no lugar de beleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 25, 'Teus homens cairão à espada; teus guerreiros na batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 3, 26, 'E as portas delas gemerão, e chorarão; e ela, ficando desolada, se sentará no chão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 4, 1, 'E sete mulheres tomarão um [mesmo] homem naquele dia, dizendo: Nós comeremos de nosso pão, e nos vestiremos de nossas roupas; [queremos] somente que teu nome seja posto sobre nós; livra-nos de nossa vergonha!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 4, 2, 'Naquele dia o Renovo do SENHOR será belo e glorioso; e o fruto da terra de excelente valor, para os de Israel que escaparem [do perigo] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 4, 3, 'E será que aquele que continuar em Sião e aquele que for deixado em Jerusalém será chamado santo; todo aquele que em Jerusalém está escrito para a vida;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 4, 4, 'Quando o Senhor lavar a imundícia das filhas de Sião, e limpar o sangue de Jerusalém do meio dela, com o espírito de juízo, e com o espírito de queima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 4, 5, 'E o SENHOR criará sobre toda moradia do monte de Sião, e sobre seus ajuntamentos, uma nuvem de dia, e uma fumaça, e um brilho de fogo inflamado de noite; porque sobre toda glória haverá proteção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 4, 6, 'E haverá uma tenda para sombra contra o calor do dia, e para refúgio e abrigo contra a tempestade e contra a chuva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 1, 'Agora cantarei a meu amado o cântico de meu querido de sua vinha: meu amado tem uma vinha, em um morro fértil;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 2, 'E a cercou, e limpou das pedras, e a plantou de excelentes videiras, e edificou no meio dela uma torre; e também fundou nela uma prensa de uvas; e esperava que desse uvas boas, porém deu uvas imprestáveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 3, 'E agora, ó moradores de Jerusalém, e vós homens de Judá? Julgai, eu vos peço, entre mim e minha vinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 4, 'O que mais podia ser feito à minha vinha, que eu não tenha já feito? Se eu esperava uvas boas, como, pois, veio dar uvas imprestáveis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 5, 'Por isso agora eu vos farei saber o que farei à minha vinha: tirarei sua cerca, para que sirva de pastagem; derrubarei seu muro, para que seja pisada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 6, 'E eu a tornarei uma [terra] abandonada; não será podada, nem cavada; mas crescerão [nela] cardos e espinhos; e darei ordens às nuvens, para que não chovam chuva sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 7, 'Porque a vinha do SENHOR dos exércitos é a casa de Israel, e os homens de Judá são suas plantas agradáveis; porém ele esperava juízo, e eis aqui opressão; [ele esperava] justiça, e eis aqui clamor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 8, 'Ai dos que juntam uma casas, [e] acumulam propriedades de terra, até que não tenha sobrado mais lugar, para que somente vós fiqueis como moradores no meio da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 9, 'O SENHOR dos exércitos [disse] aos meus ouvidos: Verdadeiramente muitas casas se tornarão desertas, [até] as grandes e valiosas ficarão sem moradores!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 10, 'E dez jeiras de vinha darão [apenas] um bato; e um ômer de semente dará [apenas] um efa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 11, 'Ai dos que se levantam cedo pela manhã, para buscarem bebida alcoólica, e continuam até a noite, [até que] o vinho os esquente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 12, 'E harpas, liras, tamborins, gaitas e vinho há em seus banquetes; porém não olham para a obra do SENHOR, nem veem a obra de suas próprias mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 13, 'Por isso meu povo será levado cativo, porque não tem conhecimento; seus nobres terão fome, e sua multidão se secará de sede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 14, 'Por isso o Xeol alargou seu avidez, e sua boca se abriu tanto que não se pode medir, e [ali] descerão a nobreza e também a multidão, em meio a barulhos e com os que festejam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 15, 'Então as pessoas serão rebaixadas, e os homens serão humilhados; e os olhos dos arrogantes se humilharão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 16, 'Mas o SENHOR dos exércitos será exaltado com juízo; e Deus, o Santo, será santificado com justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 17, 'E os cordeiros pastarão como se fosse seus próprios pastos, e os estranhos comerão [do alimento proveniente] dos lugares abandonados dos ricos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 18, 'Ai dos que puxam perversidade com cordas de futilidade, e pelo pecado como que [com] cordas de carruagens!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 19, 'E dizem: Que ele se apresse, acelere sua obra, para que a vejamos; e aproxime-se e venha o conselho do Santo de Israel, para que possamos saber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 20, 'Ai dos que chamam o mal de bem, e o bem de mal; que trocam as trevas pela luz, e a luz pelas trevas; e trocam o amargo pelo doce, e o doce pelo amargo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 21, 'Ai dos [que se acham] sábios aos seus próprios olhos, e prudentes para si mesmos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 22, 'Ai dos [que se acham] corajosos para beberem vinho, e homens fortes para misturarem bebida alcoólica!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 23, '[Ai d] os que inocentam o perverso por causa de suborno, e se desviam da justiça dos justos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 24, 'Por isso, como a língua de fogo consome a estopa, e a chama queima a palha, [assim] sua raiz será como podridão, e sua flor se desfará como o pó; pois rejeitaram a Lei do SENHOR dos exércitos, e desprezaram a palavra do Santo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 25, 'Por isso se acendeu a ira do SENHOR contra seu povo, e estendeu sua mão contra ele, e o feriu; e as montanhas tremeram, e seus cadáveres foram como lixo no meio das ruas; com tudo isto ele não retrocedeu sua ira; ao contrário, sua mão ainda está estendida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 26, 'E ele levantará uma bandeira para as nações distantes, e lhes assoviará desde os confins da terra; e eis que virão com rapidez apressadamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 27, 'Não haverá entre eles cansado ou quem tropece; ninguém cochilará, nem dormirá; nem se desatará o cinto de seus lombos, nem será arrebentada a tira de seus calçados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 28, 'Suas flechas estarão afiadas, e todos os seus arcos prontos para atirar; os cascos de seus cavalos serão comparáveis a rochas, e as rodas [de suas carruagens] como redemoinhos de vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 29, 'O rugido deles será como o de um leão feroz, e bramarão como filhotes de leão; e rugirão, e tomarão a presa, e a levarão, e não haverá quem [a] resgate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 5, 30, 'E bramarão contra ela naquele dia como o bramido do mar; então olharão para a terra, e eis que há trevas [e] aflição; e a luz se escurecerá em suas nuvens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 1, 'No ano em que o rei Uzias morreu, eu vi o Senhor sentado sobre um alto e elevado trono; e as bordas de seu manto enchiam o templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 2, 'Serafins estavam por cima dele, cada um tinha seis asas; com duas cobriam seus rostos, com duas cobriam seus pés, e com duas voavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 3, 'E clamavam uns aos outros, dizendo: Santo! Santo! Santo é o SENHOR dos exércitos! Toda a terra está cheia de sua glória!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 4, 'E as molduras das portas se moviam com a voz do que clamava; e a casa se encheu de fumaça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 5, 'Então eu disse: Ai de mim, que vou perecer! Pois sou homem de lábios impuros, e moro no meio de um povo de lábios impuros, e meus olhos viram ao Rei, o SENHOR dos exércitos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 6, 'Porém um dos serafins voou até mim, trazendo em sua mão uma brasa viva, [a qual] ele tinha tirado do altar com uma tenaz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 7, 'E com ela tocou em minha boca, e disse: Eis que isto tocou em teus lábios; assim já foi afastada [de ti] tua culpa, e purificado estás de teu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 8, 'Depois disso ouvi a voz do Senhor, que dizia: A quem enviarei? E quem irá por nós? Então eu disse: Eis-me aqui! Envia-me!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 9, 'Então ele me disse: Vai, e diz a este povo: certamente ouvireis, mas não entendereis; certamente vereis, mas não percebereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 10, 'Faze o coração deste povo se encher de gordura, e os ouvidos deles ficarem pesados, para que não vejam com seus olhos, nem ouçam com seus ouvidos, nem entendam com seus corações, e [assim] não se convertam, nem eu os cure.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 11, 'E eu disse: Até quando, Senhor?E ele respondeu: Até que as cidades sejam devastadas, [e] não fique morador algum, nem homem algum nas casas, e a terra seja devastada por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 12, 'Porque o SENHOR removerá as pessoas [dela] ,e no meio da terra será grande o abandono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 6, 13, 'Mas ainda a décima parte ficará nela, e voltará a ser consumida; [e] como uma grande árvore ou como o carvalho, em que depois de serem derrubados, [ainda] fica a base do tronco, [assim] a santa semente será a base dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 1, 'Sucedeu, pois, nos dias de Acaz, filho de Jotão, filho de Uzias, rei de Judá, que, Rezim, rei da Síria, e Peca, filho de Remalias, rei de Israel, subiram a Jerusalém para fazerem guerra contra ela; mas não conseguiram vencer a batalha contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 2, 'E avisaram à casa de Davi, dizendo: Os sírios se aliaram aos de Efraim. Então o coração dele se agitou, e também o coração de seu povo, tal como as árvores do bosque que se agitam com o vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 3, 'Então o SENHOR disse a Isaías: Agora tu e teu filho Sear-Jasube, saí ao encontro de Acaz, ao final do aqueduto do tanque superior, na estrada do campo do lavandeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 4, 'E dize-lhe: Tem cuidado, mas fica calmo; não temas, nem desanime teu coração por causa dessas duas pontas fumegantes de lenha, por causa do ardor da ira de Rezim, dos sírios, e do filho de Remalias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 5, 'Pois o sírio teve maligno conselho contra ti, com Efraim e [com] o filho de Remalias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 6, 'Vamos subir contra Judá, e o aflijamos, e o repartamos entre nós; e façamos reinar como rei no meio dele ao filho de Tabeal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 7, 'Assim diz o Senhor DEUS: Isso não subsistirá, nem sucederá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 8, 'Pois a cabeça da Síria é Damasco, e o cabeça de Damasco Rezim; e dentro de sessenta e cinco anos Efraim será quebrado, e não será [mais] povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 9, 'E a cabeça de Efraim é Samaria, e o cabeça de Samaria é o filho de Remalias. Se não crerdes, não ficareis firmes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 10, 'E o SENHOR continuou a falar a Acaz, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 11, 'Pede para ti um sinal do SENHOR teu Deus; pede ou de baixo, das profundezas, ou de cima, das alturas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 12, 'Mas Acaz disse: Não pedirei, nem porei teste ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 13, 'Então [Isaías] disse: Ouvi agora, ó casa de Davi: Achais pouco cansardes aos homens, para cansardes também [a paciência] do meu Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 14, 'Por isso o Senhor, ele mesmo, vos dará um sinal: eis que a virgem conceberá, e fará nascer um filho, e ela chamará seu nome Emanuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 15, 'Manteiga e mal ele comerá, pois saberá como rejeitar o mal e escolher o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 16, 'Mas antes que este menino saiba rejeitar o mal e escolher o bem, a terra da qual tendes pavor será desamparada de seus dois reis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 17, 'O SENHOR fará vir sobre ti, sobre o teu povo, e sobre a casa de teu pai, dias que nunca vieram, desde o dia em que Efraim se desviou de Judá, [quando vier] o rei da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 18, 'Porque acontecerá que naquele dia o SENHOR assoviará às moscas que estão na extremidade dos rios do Egito, e às abelhas que andam na terra da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 19, 'E virão, e todas elas pousarão nos vales desabitados, e nas fendas das rochas, e em todos os espinheiros, e em todos os arbustos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 20, 'Naquele dia o Senhor raspará com uma navalha alugada dalém do rio, por meio do rei da Assíria, a cabeça e os pelos dos pés; e até a barba será tirada por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 21, 'E acontecerá naquele dia, que alguém estará criando uma vaca jovem e duas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 22, 'E será que, por causa da abundância de leite que lhe derem, ele comerá manteiga; e comerá manteiga e mel todo aquele que for deixado no meio da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 23, 'Será também naquele dia, que todo lugar em que antes havia mil videiras [do valor] de dez mil moedas de prata, se tornará [lugar] para espinhos e para cardos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 24, 'Que com arco e flechas ali entrarão; porque toda a terra será espinhos e cardos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 7, 25, 'E também todos os montes onde costumavam ser cavados com enxadas, não se irá a eles por medo dos espinhos e dos cardos; porém servirão para se enviar bois, e para que gado miúdo pise.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 1, 'Disse-me também o SENHOR: Toma para ti um grande letreiro, e escreve nele com pena [para uso] humano: Maer-Salal- Has-Baz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 2, 'Então tomei comigo testemunhas fiéis: o sacerdote Urias, e Zacarias filho de Jeberequias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 3, 'E vim até a profetisa, que concebeu e teve um filho; e o SENHOR me disse: Chama o nome dele de Maer-Salal-Has-Baz,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 4, 'porque antes que o menino saiba falar “papai” ou “mamãe”, as riquezas de Damasco e os despojos de Samaria serão tomados pelo rei da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 5, 'E o SENHOR continuou a a falar comigo, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 6, 'Dado que este povo rejeitou as águas de Siloé, que correm calmamente, e se alegrou com Resim e com o filho de Remalias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 7, 'Por isso eis que o Senhor fará subir sobre eles as águas do rio fortes e impetuosas: [que é] o rei da Assíria com todo o sua glória; e subirá sobre todas as suas correntes de águas, e transbordará por todas as suas margens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 8, 'E passará por Judá, e o inundará, chegando até o pescoço; e ao estender suas asas, encherá a largura de tua terra, ó Emanuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 9, 'Ajuntai-vos, povos, e sereis quebrados; e ouvi, todos vós que sois de terras distantes; vesti vossos cintos, e sereis quebrados; preparai vossos cintos [para a batalha] ,mas sereis quebrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 10, 'Reuni-vos para tomar conselho, mas ele será desfeito; falai [alguma] palavra, porém ela não se confirmará, porque Deus é conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 11, 'Porque assim o SENHOR me disse com mão forte; e ele me ensinou a não andar pelo caminho deste povo, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 12, 'Não chameis de conspiração a tudo quanto este povo chama de conspiração; e não temais o que eles temem, nem vos assombreis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 13, '[Mas] ao SENHOR dos exércitos, a ele santificai; e ele seja ele vosso temor, e ele seja vosso assombro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 14, 'Então ele será como santuário [para vós] ; porém como pedra de ofensa, e por pedra de tropeço para as duas casas de Israel; como laço e como rede para os moradores de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 15, 'E muitos dentre eles tropeçarão e cairão; e serão quebrados, enlaçados, e presos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 16, 'Liga o testemunho; sela a Lei entre meus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 17, 'Esperarei ao SENHOR, que esconde seus rosto da casa de Jacó; e a ele aguardarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 18, 'Eis aqui, eu e os filhos que o SENHOR me deu, [somos] como sinais e como maravilhas em Israel, pelo SENHOR dos exércitos, que habita no monte de Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 19, 'E quando vos disserem: Consultai aos que se comunicam com os mortos e aos encantadores que murmuram, sussurrando entre os dentes.Por acaso não deveria o povo consultar ao seu Deus? [Perguntarão] aos mortos por causa dos vivos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 20, '[Respondei] : À Lei e ao testemunho!Se não falarem segundo esta palavra, não haverá amanhecer para eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 21, 'E passarão pela [terra] ,duramente oprimidos e famintos; e será que, quando tiverem fome e ficarem enfurecidos, então amaldiçoarão ao seu rei e ao seu Deus, olhando para cima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 8, 22, 'E olhando para a terra, eis aflição e trevas; [haverá] angustiante escuridão, e para as trevas serão empurrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 1, 'Mas não [haverá] escuridão para aquela que foi angustiada tal como nos primeiros tempos, [quando] ele afligiu a terra de Zebulom e a terra de Naftali; mas depois ele [a] honrará junto ao caminho do mar, dalém do Jordão, a Galileia das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 2, 'O povo que andava em trevas viu uma grande luz; os que habitavam em terra de sombra de morte, uma luz brilhou sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 3, 'Tu multiplicaste a este povo, aumentaste-lhe a alegria. Eles se alegraram diante de ti como a alegria da ceifa, como quando ficam contentes ao repartir despojos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 4, 'Pois tu quebraste o jugo de sua carga, e a vara de seus ombros, o bastão daquele que opressivamente o conduzia, como no dia dos midianitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 5, 'Quando toda a batalha daqueles que batalhavam era feita com ruído, e as roupas se revolviam em sangue, e eram queimadas [para servir] de combustível ao fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 6, 'Porque um menino nos nasceu, um filho nos foi dado; e o governo está sobre seus ombros; e seu nome se chama Maravilhoso, Conselheiro, Deus Forte, Pai da Eternidade, Príncipe da Paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 7, 'À grandeza de [seu] governo e à paz não haverá fim, sobre o trono de Davi, e sobre seu reino, para o firmar e fortalecer com juízo e justiça desde agora e para sempre; o zelo do SENHOR dos exércitos fará isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 8, 'O Senhor enviou uma palavra a Jacó, e ela caiu sobre Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 9, 'E todo o povo [a] saberá: Efraim, e os moradores de Samaria, em soberba e arrogância de coração, dizem:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 10, 'Os tijolos caíram, mas construiremos de novo com pedras talhadas; as figueiras bravas foram cortadas, mas as trocaremos por cedros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 11, 'Por isso o SENHOR levantará os adversários de Resim contra ele, e instigará seus inimigos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 12, 'Pela frente [virão] os sírios, e por trás os filisteus; e devorarão a Israel com a boca aberta. Nem com tudo isto sua ira cessará, e ainda sua mão está estendida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 13, 'Porque este povo não se converteu àquele que o feriu, nem busca ao SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 14, 'Por isso o SENHOR cortará de Israel a cabeça, a cauda, o ramo e o junco de Israel em um único dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 15, 'O ancião e o homem respeitado, este é a cabeça; e o profeta que ensina falsidade é a cauda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 16, 'Pois os guias deste povo são enganadores; e os que por eles forem guiados estão a ponto de serem destruídos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 17, 'Por causa disso o Senhor não terá alegria em seus rapazes, e não terá piedade de seus órfãos e de suas viúvas; porque todos eles são hipócritas e malfeitores, e toda boca fala tolices; nem com tudo isto sua ira cessará, e sua mão ainda está estendida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 18, 'Pois a perversidade queima como fogo, [que] consumirá cardos e espinhos, e incendiará aos emaranhados das árvores da floresta; e subirão como nuvens de fumaça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 19, 'Pelo furor do SENHOR dos exércitos a terra se inflamará, e o povo será como o combustível do fogo; cada um não terá piedade do outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 20, 'Se cortar à direita, ainda terá fome; e se comer da esquerda, ainda não se saciará; cada um comerá a carne de seu [próprio] braço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 9, 21, 'Manassés a Efraim, e Efraim a Manassés; e eles ambos serão contra Judá; e nem com tudo isto sua ira cessará, e sua mão ainda está estendida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 1, 'Ai dos que decretam ordenanças injustas, e dos que escribas que escrevem coisas opressivas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 2, 'Para afastarem aos pobres de seu direito, e para tomarem o direito dos pobres de meu povo; para despojarem as viúvas, e para roubarem aos órfãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 3, 'Mas que fareis no dia da visitação e da assolação, [que] virá de longe? A quem recorrereis por socorro? E onde deixareis vossa glória?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 4, '[Nada podem fazer] ,a não ser se abaterem entre os presos, e caírem entre os mortos. Com tudo isto, sua ira não cessará, e sua mão ainda está estendida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 5, 'Ai da Assíria, a vara de minha ira; porque minha indignação é pão em suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 6, 'Eu a enviarei contra um povo corrompido, e lhe darei ordem contra um povo do qual me enfureço; para que roube ao roubo, e despoje ao despojo, e para que o pisem como a lama das ruas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 7, 'Ainda que ela não pense assim, nem pretenda isso seu coração; em vez disso, [deseja] em seu coração destruir e eliminar não poucas nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 8, 'Pois diz: Por acaso os meus generais, não são todos eles reis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 9, 'Não é Calno como Carquemis? Não é Hamate como Arpade? Não é Samaria como Damasco?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 10, 'Assim como minha mão tomou aos reinos dos ídolos, cujas imagens eram melhores que Jerusalém e as de Samaria,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 11, 'Por acaso não farei eu a Jerusalém e a seus ídolos da mesma maneira que fiz a Samaria e a seus ídolos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 12, 'Porque acontecerá que, quando o Senhor tiver acabado toda sua obra no monte de Sião em Jerusalém, então: Visitarei [para castigar] o fruto da arrogância da rei da Assíria e a pompa do orgulho de seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 13, 'Pois ele diz: Fiz [isso] com a força de minha mão e com minha sabedoria, pois sou esperto; e tirei as fronteiras dos povos, e roubei seus bens, e como guerreiro abati aos moradores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 14, 'E minha mão tomou as riquezas dos povos como a um ninho; e como se juntam ovos abandonados, assim eu juntei toda a terra; e não houve quem movesse asa, ou abrisse boca, ou fizesse ruído.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 15, 'Por acaso o machado se glorificará contra aquele que com ele corta? Ou a serra se engrandecerá contra aquele que a manuseia? [Seria] como se fosse o bastão que movesse aos que o levantam, como se a vara fosse capaz de levantar, [como se ela] não [fosse apenas] madeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 16, 'Por isso o Senhor DEUS dos exércitos enviará magreza entre seus gordos; e em lugar de sua glória ele inflamará um incêndio, como um incêndio de fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 17, 'E a Luz de Israel virá a ser fogo, e seu Santo, labareda, que queima e consome seus espinhos e seus cardos em um dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 18, 'Também consumirá a glória de sua floresta, e de seu campo fértil, desde a alma até a carne; e será como quando um doente se definha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 19, 'E o resto das árvores de sua floresta será tão pouco em número, que um menino será capaz de contá-las.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 20, 'E acontecerá naquele dia, que os restantes de Israel e os que escaparam da casa de Jacó nunca mais confiarão naquele que os feriu; ao invés disso, confiarão verdadeiramente no SENHOR, o Santo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 21, 'Os restantes se converterão, os restantes de Jacó, ao Deus Forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 22, 'Porque ainda que teu povo, ó Israel, seja como a areia do mar, [apenas] o restante dele se converterá; a destruição já está decretada, transbordante em justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 23, 'Pois a destruição que foi decretada, o Senhor DEUS dos exércitos a executará no meio de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 24, 'Por isso assim diz o Senhor DEUS dos exércitos: Não temas, povo meu, que habita em Sião, ao assírio, quando te ferir com vara, e contra ti levantar seu bastão da maneira dos egípcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 25, 'Pois em breve se completará a indignação e a minha ira, para os consumir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 26, 'Pois o SENHOR dos exércitos levantará um açoite contra ele, como a matança de Midiã junto à rocha de Orebe; e sua vara [estará] sobre o mar, a qual ele levantará da maneira [que ele fez] aos egípcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 27, 'E acontecerá naquele dia, que sua carga será tirada de teu ombro, e seu jugo de teu pescoço; e o jugo será despedaçado por causa da unção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 28, 'Eles, [os assírios] ,chegaram a Aiate, passaram por Migrom, em Micmás puseram seus instrumentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 29, 'Passaram o vau, se abrigaram em Geba. Ramá está tremendo, Gibeá de Saul está fugindo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 30, 'Grita com tua voz, ó filha de Galim! Ouve, Laís! Pobre de ti, Anatote!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 31, 'Madmena foge; os moradores de Gebim procuram refúgios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 32, 'Ainda hoje parará em Nobe; moverá sua mão [contra] o monte da Filha de Sião, o morro de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 33, 'Eis que o Senhor DEUS dos exércitos cortará os galhos com violência; e os de alta estatura serão cortados, e os elevados serão abatidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 10, 34, 'E cortará os emaranhados da floresta com machado de ferro; e o Líbano cairá pelo Grandioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 1, 'E uma vara brotará do tronco cortado de Jessé; e um ramo crescerá de suas raízes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 2, 'E repousará sobre ele o Espírito do SENHOR: o Espírito de sabedoria e de entendimento, o Espírito de conselho e força, o Espírito de conhecimento e temor ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 3, 'E seu prazer será no temor ao SENHOR; e não julgará segundo a vista de seus olhos, nem repreenderá segundo o ouvir de seus ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 4, 'Mas julgará com justiça aos pobres, e repreenderá com equidade aos humildes da terra; porém ferirá a terra com a vara de sua boca, e com o espírito de seus lábios matará ao perverso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 5, 'E a justiça será o cinto de sua cintura; a fidelidade o cinto de seus lombos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 6, 'E o lobo morará com o cordeiro, e o leopardo se deitará com o cabrito; e o bezerro, o filhote de leão, e o animal cevado [andarão] juntos, e um menino pequeno os guiará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 7, 'A vaca e a ursa se alimentarão juntas, seus filhos [juntos] se deitarão; e o leão comerá palha como o boi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 8, 'A criança que ainda mama brincará sobre a toca da serpente, e a que for desmamada porá sua mão na cova da víbora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 9, 'Não se fará mal nem dano algum em todo o meu santo monte, porque a terra se encherá do conhecimento do SENHOR, como as águas cobrem o mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 10, 'E acontecerá naquele dia, que as nações buscarão a raiz de Jessé, posta como bandeira dos povos; e seu repouso será glorioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 11, 'E acontecerá naquele dia, que o Senhor voltará a pôr sua mão para adquirir de novo aos restantes de seus povo, que restarem da Assíria, do Egito, Patros, Cuxe, Elão, Sinear, Hamate, e das ilhas do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 12, 'E levantará uma bandeira entre as nações, e juntará aos desterrados de Israel, e reunirá aos dispersos de Judá desde os quatro confins da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 13, 'E a inveja de Efraim terminará, e os adversários de Judá serão cortados; Efraim não invejará a Judá, e Judá não oprimirá a Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 14, 'Em vez disso, voarão sobre os ombros dos filisteus ao ocidente, e juntos despojarão aos do oriente; porão suas mãos [sobre] Edom e Moabe, e os filhos de Amom lhes obedecerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 15, 'E o SENHOR dividirá a porção de mar do Egito, e moverá sua mão contra o rio com a força de seu vento; e o ferirá em sete correntes, e fará com que se possa atravessá-lo com sandálias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 11, 16, 'E haverá um caminho para os restantes de seu povo, que restarem da Assíria, assim como aconteceu a Israel, no dia em que subiu da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 12, 1, 'E tu dirás naquele dia: Eu te agradeço, SENHOR, pois, ainda que tenhas te irado contra mim, tua ira foi removida, e tu me consolas!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 12, 2, 'Eis que Deus é minha salvação; [nele] confiarei, e não terei medo; porque minha força e minha canção é o SENHOR DEUS; e ele tem sido minha salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 12, 3, 'E alegremente tirareis águas das fontes da salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 12, 4, 'E direis naquele dia: Agradecei ao SENHOR, falai em alta voz ao seu nome; informai seus feitos entre os povos, anunciai quão exaltado é o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 12, 5, 'Cantai ao SENHOR, porque ele fez coisas grandiosas; que isto seja conhecido em toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 12, 6, 'Grita e canta de alegria, ó moradora de Sião; porque o Santo de Israel é grande no meio de ti!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 1, 'Revelação sobre a Babilônia, vista por Isaías, filho de Amoz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 2, 'Levantai uma bandeira sobre um alto monte, levantai a voz a eles; movei a mão ao alto, para que entrem pelas portas dos príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 3, 'Eu dei ordens aos meus santificados; também chamei aos meus guerreiros para minha ira, aos que se alegram com minha glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 4, 'Há um ruído de tumulto sobre os montes, como o de um imenso povo; ruído de multidões de reinos de nações reunidas; o SENHOR dos exércitos está revistando um exército para a guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 5, 'Eles vêm de uma terra distante, desde a extremidade do céu; o SENHOR e os instrumentos de seu furor, para destruir toda [aquela] terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 6, 'Gritai lamentando, pois o dia do SENHOR está perto; vem como assolação pelo Todo-Poderoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 7, 'Por isso todas as mãos ficarão fracas, e o coração de todos os homens se derreterá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 8, 'E ficarão aterrorizados; serão tomados por dores e angústias; sofrerão como mulher com dores de parto; cada um terá medo de seu próximo, seus rostos serão rostos em chamas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 9, 'Eis que o dia do SENHOR vem horrendo, com furor e ira ardente, para pôr a terra em assolação, e destruir os pecadores nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 10, 'Porque as estrelas dos céus e suas constelações não darão sua luz; o sol se escurecerá ao nascer, e a lua não brilhará com sua luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 11, 'Porque visitarei para punir sobre o mundo a maldade, e sobre os maus sua perversidade; e porei fim à arrogância dos soberbos, e abaterei o orgulho dos tiranos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 12, 'Farei com que um varão seja mais raro que o ouro maciço, e um homem mais que o ouro fino de Ofir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 13, 'Por isso farei estremecer aos céus, e a terra se moverá de seu lugar, por causa do furor do SENHOR dos exércitos, e por causa de sua ardente ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 14, 'E será que, como uma corça em fuga, e como uma ovelha que ninguém recolhe, cada um se voltará para seu povo, e cada um fugirá para sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 15, 'Qualquer um que for achado, será traspassado; e qualquer um que se juntar a ele cairá pela espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 16, 'E suas crianças serão despedaçadas perante seus olhos; suas casas serão saqueadas, e suas mulheres estupradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 17, 'Eis que despertarei contra eles aos medos, que não se importarão com a prata, nem desejarão ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 18, 'E [com seus] arcos despedaçarão aos rapazes, e não terão piedade do fruto do ventre; o olho deles não terá compaixão das crianças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 19, 'Assim será Babilônia, a joia dos reinos, a beleza e o orgulho dos caldeus, semelhante a Sodoma e Gomorra, quando Deus [as] arruinou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 20, 'Nunca mais será habitada, nem [nela] se morará, de geração em geração; nem o árabe armará ali sua tenda, nem os pastores farão descansar ali [seus] rebanhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 21, 'Mas os animais selvagens do deserto ali descansarão, e suas casas se encherão de animais medonhos; e ali habitarão corujas, e bodes selvagens saltarão ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 13, 22, 'E as hienas uivarão em suas fortalezas, e chacais em seus confortáveis palácios. Pois está chegando bem perto o seu tempo, e os dias dela não se prolongarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 1, 'Porque o SENHOR terá piedade de Jacó, e ainda escolherá a Israel, e os porá em sua terra; e estrangeiros se juntarão a eles, e se apegarão à casa de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 2, 'E os povos os receberão, e os levarão a seus lugares, e a casa de Israel terá posse deles como servos e servas, na terra do SENHOR; e capturarão aos que tinham lhes capturado, e dominarão sobre seus opressores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 3, 'E será que, no dia em que o SENHOR te der descanso de teu trabalho e de teu tormento, e da dura escravidão que te escravizaram,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 4, 'Então levantarás estas palavras de escárnio contra o rei da Babilônia, e dirás: [Vede] como foi o fim do opressor, como a cidade dourada se acabou!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 5, 'O SENHOR quebrou o bastão dos perversos, o cetro dos que dominavam,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 6, 'Que feria aos povos com furor com golpes sem fim, que com ira dominava as nações, perseguindo sem compaixão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 7, 'A terra descansa, já está sossegada; gritam de prazer com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 8, 'Até os pinheiros se alegram por causa de ti, e os cedros do Líbano, dizendo: Desde que caíste, ninguém mais sobe contra nós para nos cortar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 9, 'O Xeol desde as profundezas se agitou por causa de ti, para sair ao teu encontro em tua chegada; por causa de ti ele despertou os mortos, todos os líderes da terra, e fez levantar de seus tronos todos os reis das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 10, 'Todos eles responderão e te dirão: Tu te enfraqueceste como nós, e te tornaste semelhante a nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 11, 'Tua soberba foi derrubada ao Xeol, assim como o som de tuas harpas; larvas se espalharão por debaixo de ti, e vermes te cobrirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 12, 'Como caíste do céu, ó “luminoso”, filho do amanhecer! Cortado foste até a terra, tu que enfraquecias as nações!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 13, 'E dizias em teu coração: Subirei ao céu; levantarei o meu trono acima das estrelas de Deus, e me sentarei no monte da congregação, nas regiões distantes do norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 14, 'Subirei sobre as alturas das nuvens, e serei semelhante ao Altíssimo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 15, 'Porém tu serás derrubado ao Xeol, às profundezas da cova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 16, 'Os que te olharem prestarão atenção em ti, pensarão, [e dirão] : É este o homem que abalava a terra, e fazia os reinos tremerem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 17, 'Que fazia do mundo como um deserto, e arruinava suas cidades? Que nunca soltava seus prisioneiros para [suas] casas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 18, 'Todos os reis das nações, eles todos, jazem com honra, cada um em sua própria casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 19, 'Porém tu és lançado de tua sepultura, como um ramo repugnante, [como] as roupas dos que foram mortos, traspassados à espada; [como] os que descem às pedras da cova, como um corpo pisoteado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 20, 'Não se juntará a eles na sepultura, porque destruíste tua terra, [e] mataste a teu povo; a semente dos malignos não será nomeada para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 21, 'Preparai a matança para seus filhos por causa da maldade de seus pais; para que não se levantem, e tomem posse da terra, e encham a face do mundo de cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 22, 'Porque me levantarei contra eles,diz o SENHOR dos exércitos; e cortarei para eliminar da Babilônia o nome e os restantes, o filho e o neto, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 23, 'E eu a porei como propriedade de corujas, e poças d´água; e a varrerei com a vassoura da destruição,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 24, 'O SENHOR dos exércitos jurou, dizendo: Com certeza acontecerá assim como pensei, e será comprido assim como determinei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 25, 'Quebrarei a Assíria em minha terra, e em minhas montanhas eu a esmagarei; para que seu jugo se afaste deles, e sua carga seja tirada de seus ombros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 26, 'Este é o plano determinado para toda a terra; e esta é a mão que está estendida sobre todas as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 27, 'Pois o SENHOR dos exércitos já determinou; quem invalidará? E sua mão já está estendida; quem [a] retrocederá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 28, 'No ano em que o rei Acaz morreu, houve esta revelação:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 29, 'Não te alegres, ó tu, Filisteia inteira, por ter sido quebrada a vara que te feria; porque da raiz da cobra sairá uma víbora, e seu fruto será uma venenosa serpente voadora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 30, 'E os mais pobres serão apascentados, e os necessitados deitarão em segurança; porém farei tua raiz morrer de fome, e ela matará teus sobreviventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 31, 'Uiva, ó porta! Grita, ó cidade! Tu, Filisteia inteira, estás a ser derretida; porque do norte vem fumaça, e não há solitário em seus batalhões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 14, 32, 'Que, pois, se responderá aos mensageiros d [aquela] nação? Que o SENHOR fundou a Sião, e que nela os oprimidos de seu povo terão refúgio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 15, 1, 'Revelação sobre Moabe: Certamente em uma noite é destruída Ar-Moabe; [e] é devastada; certamente em uma noite é destruída Quir-Moabe, [e] é devastada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 15, 2, '[Os moradores] sobem ao templo, e a Dibom, aos lugares altos, para chorar; Moabe grita de lamento por Nebo e por Medeba; em todas as suas cabeças há calva, e toda barba está raspada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 15, 3, 'Eles se vestem de sacos em suas ruas; em seus terraços, e em suas praças todos andam gritando de lamento, e descem chorando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 15, 4, 'Tanto Hesbom como Eleale vão gritando, até Jaaz se ouve sua voz; por causa disso os soldados armados de Moabe gritam, a alma de cada um está abalada dentro de si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 15, 5, 'Meu coração dá gritos por Moabe, seus fugitivos [foram] até Zoar [e] Eglate-Selisia; pois sobem com choro pela subida de Luíte, pois no caminho de Horonaim levantam um grito de desespero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 15, 6, 'Pois as águas de Ninrim se acabaram; pois a grama se secou, as plantas pereceram, e não há mais vegetal verde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 15, 7, 'Por isso levarão os bens que acumularam e seus pertences ao ribeiro dos salgueiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 15, 8, 'Porque o pranto rodeia aos limites de Moabe; até Eglaim chega seu grito de lamento, e até Beer-Elim sua lamentação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 15, 9, 'Pois as águas de Dimom estão cheias de sangue, porém porei em Dimom ainda outros mais: um leão aos que escaparem de Moabe, e aos sobreviventes da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 1, 'Enviai os cordeiros ao dominador da terra desde Sela pelo deserto, ao monte da filha de Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 2, 'Pois será que, como o pássaro vagueante, lançado do ninho, assim serão as filhas de Moabe junto aos vaus de Arnom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 3, 'Toma conselho, faze juízo, põe tua sombra no pino do meio dia como a noite; esconde aos exilados, [e] não exponhas os fugitivos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 4, 'Habitem entre ti teus prisioneiros, Moabe; sê tu refúgio para eles da presença do destruidor, porque o opressor terá fim, a destruição terminará, e os esmagadores serão consumidos de sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 5, 'Porque o trono se firmará em bondade, e sobre ele no tabernáculo de Davi em verdade se sentará um que julgue, e busque o juízo, e se apresse para a justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 6, 'Já ouvimos a soberba de Moabe, o arrogante ao extremo; sua arrogância, soberba e furor, [mas] seus orgulhos não são [firmes] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 7, 'Por isso Moabe gritará de lamento por Moabe; todos eles gritarão de lamento; gemereis pelos fundamentos de Quir-Haresete, pois estão quebrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 8, 'Pois os campos de Hesbom enfraqueceram, [e também] a vinha de Sibma, os senhores das nações esmagaram suas melhores plantas, que chegavam a Jezer, [e] alcançavam o deserto; seus ramos se estendiam, e passavam até o mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 9, 'Por isso lamentarei com pranto por Jezer, a vide de Sibma; eu te regarei com minhas lágrimas, ó Hesbom e Eleale; pois a alegria de teus frutos de verão e de tua colheita caiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 10, 'E foram tirados a alegria e o prazer do campo frutífero; e nas vinhas não se canta, nem grito de alegria se faz; o pisador não pisará as uvas nas prensas; eu pus fim aos clamores de alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 11, 'Por isso meus órgãos fazem ruído por Moabe como um harpa; e meu interior por Quir- Heres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 12, 'E será que, quando [o povo de] Moabe se apresentar e se cansar nos lugares altos, e entrarem em seus templo para orar, nada conseguirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 13, 'Esta é a palavra que o SENHOR falou sobre Moabe desde então.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 16, 14, 'Mas agora [assim] fala o SENHOR, dizendo: Dentro de três anos, (tais como anos de empregado), então se tornará desprezível a glória de Moabe, com toda a sua grande multidão; e os restantes serão muito poucos e sem poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 1, 'Revelação sobre Damasco: Eis que Damasco será tirada [de tal maneira] que não será mais uma cidade, mas sim, um amontoado de ruínas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 2, 'As cidades de Aroer serão abandonadas; serão para os rebanhos, e [ali] se deitarão, sem haver quem os espante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 3, 'E a fortaleza de Efraim se acabará, como também o reino de Damasco, e os restantes dos sírios; serão como a glória dos filhos de Israel,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 4, 'E será naquele dia, que a glória de Jacó se definhará, e a gordura de sua carne emagrecerá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 5, 'Pois será como o ceifeiro, que colhe os grãos, e com seu braço ceifa as espigas; será também como o que colhe espigas no vale de Refaim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 6, 'Porém ainda ficarão nele [algumas] sobras, como no sacudir da oliveira, dois [ou] três azeitonas [ficam] na ponta mais alta dos ramos, e quatro [ou] cinco em seus ramos frutíferos,diz o SENHOR, o Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 7, 'Naquele dia o homem dará atenção ao seu Criador, e seus olhos olharão ao Santo de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 8, 'E não dará atenção aos altares, obra de suas [próprias] mãos, nem olharão para o que seus [próprios] dedos fizeram, nem para os mastros de Aserá, nem para os altares de incenso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 9, 'Naquele dia suas cidades fortificadas serão como plantas abandonadas e os mais altos ramos, os quais eles abandonaram por causa dos filhos de Israel. E haverá assolação,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 10, 'Pois te esqueceste do Deus de tua salvação, e não te lembraste da rocha de tua fortaleza. Por isso, tu cultivarás belas plantas, e as cercarás de ramos estranhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 11, 'No dia que as plantares, tu as farás crescer, e pela manhã farás com que tua semente brote; porém a colheita será perdida no dia de sofrimento e de dores insuportáveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 12, 'Ai da multidão dos muitos povos, que bramam como o bramido do mar; e do rugido das nações, que rugem como o rugido de águas impetuosas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 13, 'As nações rugirão, como o rugido de muitas águas, porém [Deus] as repreenderá, e elas fugirão para longe. Serão levadas a fugirem como restos de palhas nos montes diante do vento, como coisas que rolam perante um redemoinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 17, 14, 'Ao tempo da tarde eis que há pavor; [mas] antes que amanheça não há mais: Esta é a parte daqueles que nos despojam, e o futuro reservado para aqueles que nos saqueiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 18, 1, 'Ai da terra dos zumbidos de asas, que está além dos rios de Cuxe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 18, 2, 'Que envia embaixadores pelo mar, e em navios de junco sobre as águas, [com a ordem] : Ide, mensageiros velozes, a uma nação [de gente] alta e de pele lisa, a um povo temido desde seus territórios afora, uma nação dominadora e esmagadora, cuja terra os rios dividem.')
